INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10006, -470.0, "リンド", "2023/12/22 14:59:59", 2, 2, 2002, 0.0, 127702, 0.0, "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", "2023/09/15 15:00:00", 2, 2);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10007, -470.0, "ヴルム", "2023/12/22 14:59:59", 1, 1, 2002, 0.0, 127802, 0.0, "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", "2023/09/15 15:00:00", 2, 1);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10008, -470.0, "ヴルム", "2023/12/22 14:59:59", 2, 1, 2002, 6.5, 127802, 0.0, "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", "2023/09/15 15:00:00", 2, 2);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10009, -470.0, "アネモネ", "2024/03/22 14:59:59", 1, 1, 2002, 0.0, 129602, 0.0, "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", "2023/12/15 15:00:00", 3, 2);
