INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10011, -470.0, "ネフィ=ネラ", "2024/03/22 14:59:59", 1, 1, 2002, 0.0, 129701, 0.0, "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", "2023/12/15 15:00:00", 3, 1);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10012, -470.0, "ネフィ=ネラ", "2024/03/22 14:59:59", 2, 1, 2002, 6.2, 129701, 0.0, "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", "2023/12/15 15:00:00", 3, 2);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10013, -470.0, "カノン", "2024/06/22 14:59:59", 1, 5, 2002, 3.1, 130301, 0.0, "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", "2024/03/15 15:00:00", 4, 3);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10014, -470.0, "カノン", "2024/06/22 14:59:59", 2, 2, 2002, 6.15, 130301, 0.0, "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", "2024/03/15 15:00:00", 4, 3);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10015, -470.0, "ナーナ", "2024/06/22 14:59:59", 1, 2, 2002, 0.0, 130401, 0.0, "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", "2024/03/15 15:00:00", 4, 2);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10016, -470.0, "ナーナ", "2024/06/22 14:59:59", 2, 1, 2002, 3.35, 130401, 0.0, "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", "2024/03/15 15:00:00", 4, 2);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10017, -470.0, "ホウオウ", "2024/09/22 14:59:59", 1, 1, 2002, 0.0, 130502, 0.0, "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", "2024/06/15 15:00:00", 5, 1);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10018, -470.0, "ホウオウ", "2024/09/22 14:59:59", 2, 1, 2002, 3.18, 130502, 0.0, "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", "2024/06/15 15:00:00", 5, 2);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10019, -470.0, "ホウオウ", "2024/09/22 14:59:59", 3, 4, 2002, 0.0, 130503, 0.0, "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", "2024/06/15 15:00:00", 5, 4);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10020, -470.0, "ネア", "2024/09/22 14:59:59", 1, 2, 2002, 4.9, 123301, 0.0, "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", "2024/06/15 15:00:00", 5, 1);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10021, -470.0, "ネア", "2024/09/22 14:59:59", 2, 2, 2002, 4.8, 123301, 0.0, "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", "2024/06/15 15:00:00", 5, 1);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10022, -470.0, "カリザ", "2024/12/22 14:59:59", 1, 1, 2002, 4.922, 133301, 0.0, "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", "2024/09/15 15:00:00", 6, 3);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10023, -470.0, "カリザ", "2024/12/22 14:59:59", 2, 5, 2002, 9.638, 133301, 0.0, "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", "2024/09/15 15:00:00", 6, 3);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10024, -470.0, "ミーア", "2024/12/22 14:59:59", 1, 2, 2002, 2.88, 133401, 0.0, "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", "2024/09/15 15:00:00", 6, 1);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10025, -470.0, "ミーア", "2024/12/22 14:59:59", 2, 1, 2002, 4.818, 133401, 0.0, "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", "2024/09/15 15:00:00", 6, 5);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10026, -470.0, "グレイス", "2025/03/22 14:59:59", 1, 1, 2002, 1.78, 133002, 0.0, "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", "2024/12/15 15:00:00", 7, 2);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10027, -470.0, "グレイス", "2025/03/22 14:59:59", 2, 7, 2002, 6.15, 133002, 0.0, "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", "2024/12/15 15:00:00", 7, 1);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10028, -470.0, "ヴァイオレット", "2025/03/22 14:59:59", 1, 2, 2002, 4.28, 133102, 0.0, "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", "2024/12/15 15:00:00", 7, 6);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10029, -470.0, "ヴァイオレット", "2025/03/22 14:59:59", 2, 1, 2002, 0.0, 133102, 0.0, "じめじめした商品は\nございませんので\n安心してお買い求め下さい", "2024/12/15 15:00:00", 7, 1);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10030, -470.0, "ルルィ", "2025/06/23 14:59:59", 1, 1, 2002, 5.53, 136902, 0.0, "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", "2025/03/15 15:00:00", 8, 2);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10031, -470.0, "ルルィ", "2025/06/23 14:59:59", 2, 7, 2002, 6.05, 136902, 0.0, "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", "2025/03/15 15:00:00", 8, 9);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10032, -470.0, "デュラン", "2025/06/23 14:59:59", 1, 1, 2002, 0.0, 137001, 0.0, "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", "2025/03/15 15:00:00", 8, 2);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10033, -470.0, "デュラン", "2025/06/23 14:59:59", 2, 1, 2002, 0.0, 137001, 0.0, "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", "2025/03/15 15:00:00", 8, 2);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10034, -470.0, "サツキ", "2025/09/23 14:59:59", 1, 2, 2002, 0.0, 135902, 0.0, "おう\n好きなもん持ってきな", "2025/06/16 15:00:00", 9, 2);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10035, -470.0, "サツキ", "2025/09/23 14:59:59", 2, 6, 2002, 4.935, 135902, 0.0, "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", "2025/06/16 15:00:00", 9, 1);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10036, -470.0, "ユキノ", "2025/09/23 14:59:59", 1, 5, 2002, 7.441, 135802, 0.0, "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", "2025/06/16 15:00:00", 9, 2);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10037, -470.0, "ユキノ", "2025/09/23 14:59:59", 2, 7, 2002, 0.0, 135802, 0.0, "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", "2025/06/16 15:00:00", 9, 7);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10038, -470.0, "クルル", "2025/12/22 14:59:59", 1, 2, 2002, 2.295, 130901, 0.0, "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", "2025/09/16 15:00:00", 10, 2);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10039, -470.0, "クルル", "2025/12/22 14:59:59", 2, 6, 2002, 6.281, 130901, 0.0, "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", "2025/09/16 15:00:00", 10, 1);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10040, -470.0, "ヴォルガーノ", "2025/12/22 14:59:59", 1, 1, 2002, 5.549, 137701, 0.0, "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", "2025/09/16 15:00:00", 10, 2);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10041, -470.0, "ヴォルガーノ", "2025/12/22 14:59:59", 2, 6, 2002, 2.64, 137701, 0.0, "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", "2025/09/16 15:00:00", 10, 3);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10042, -470.0, "ライラエル", "2026/03/23 11:59:59", 1, 4, 2002, 7.642, 132801, 0.0, "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", "2025/12/15 15:00:00", 11, 7);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10043, -470.0, "ライラエル", "2026/03/23 11:59:59", 2, 1, 2002, 0.0, 132802, 0.0, "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", "2025/12/15 15:00:00", 11, 1);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10044, -470.0, "クローチェ", "2026/03/23 11:59:59", 1, 1, 2002, 0.0, 134502, 0.0, "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", "2025/12/15 15:00:00", 11, 1);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10045, -470.0, "クローチェ", "2026/03/23 11:59:59", 2, 1, 2002, 3.72, 134501, 0.0, "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", "2025/12/15 15:00:00", 11, 2);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10046, -470.0, "ネフィ＝ネラ", "2026/06/22 11:59:59", 1, 1, 2002, 4.991, 138201, 0.0, "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", "2026/03/16 12:00:00", 12, 2);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10047, -470.0, "ネフィ＝ネラ", "2026/06/22 11:59:59", 2, 4, 2002, 3.877, 138201, 0.0, "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", "2026/03/16 12:00:00", 12, 1);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10048, -470.0, "アラクネ", "2026/06/22 11:59:59", 1, 6, 2002, 1.71, 136001, 0.0, "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", "2026/03/16 12:00:00", 12, 4);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10049, -470.0, "アラクネ", "2026/06/22 11:59:59", 2, 2, 2002, 5.32, 136001, 0.0, "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", "2026/03/16 12:00:00", 12, 5);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10050, -470.0, "アネモネ", "2026/09/22 11:59:59", 1, 4, 2002, 3.727, 135401, 0.0, "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", "2026/06/15 12:00:00", 13, 9);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10051, -470.0, "アネモネ", "2026/09/22 11:59:59", 2, 9, 2002, 7.213, 135401, 0.0, "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", "2026/06/15 12:00:00", 13, 7);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10052, -470.0, "クリア", "2026/09/22 11:59:59", 1, 2, 2002, 1.874, 135301, 0.0, "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", "2026/06/15 12:00:00", 13, 1);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (10053, -470.0, "クリア", "2026/09/22 11:59:59", 2, 2, 2002, 0.0, 135301, 0.0, "アルバイトが終わったら\n海に遊びに行きましょう！\nモネちゃんも一緒に♪", "2026/06/15 12:00:00", 13, 2);
